// === Tab: sin waves ===
var size = 10;//size inversely proportional to # circles
var vel = .004;//speed of first circle

setup=_=> {
	createCanvas(windowWidth, windowHeight);
	circles = []
	for(var x = size,y = windowHeight/2;x<windowWidth-size;x+=size*2){
		circles.push(new circle(x,y));//array of objects
	}
}
draw =_=> {
	clear();
	for(var i = 0;i<circles.length;i++){
		if(((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && i<circles.length-3){
			line(circles[i].x,circles[i].y,circles[i+1].x,circles[i+1].y);
			line(circles[i].x,circles[i].y,circles[i+2].x,circles[i+2].y);
			line(circles[i].x,circles[i].y,circles[i+3].x,circles[i+3].y);
		}
		circles[i].create();
		circles[i].theta+=circles[i].vel;//increasing theta moves each invdividual circle vertically
	}
}
class circle{
	constructor(x,y){
		this.x = x;
		this.y = y;
		this.theta = 0;
		this.vel = vel;
		vel+=.002;//each consecutive circle faster than previous
	}
	create(){//calc y position and draw circle
		fill(this.x-windowHeight/2+100,this.y-windowHeight/2+100,this.y-windowHeight/2+100);//color gradient
		this.y=sin(this.theta)*100+windowHeight/2;
		ellipse(this.x, this.y, size*2, size*2);
	}
}

